# Consultar o estado RPKI de um prefixo antes e depois do ROA

$ routinator vrps --filter-prefix 200.130.0.0/16
ASN,Prefix,Max Length,Trust Anchor
AS64500,200.130.0.0/16,24,lacnic

# Estado da rota no roteador (Cisco IOS-XR)
RP/0/0/CPU0:router# show bgp 200.130.5.0/24
  Path #1: Received by speaker 0
  origin-AS validity: invalid          <-- ROA existe, origem não bate
  64496
    198.51.100.1 from 198.51.100.1

# Política que descarta Invalid (JunOS)
policy-statement rpki-check {
    term invalid {
        from validation-database invalid;
        then reject;
    }
    term unknown {
        from validation-database unknown;
        then { local-preference 90; accept; }
    }
    term valid {
        from validation-database valid;
        then { local-preference 110; accept; }
    }
}

# Rejeitar Invalid só funciona se o validador estiver ativo.
# Validador fora do ar => tudo vira Unknown => nada é bloqueado.
